def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    opponent_x, opponent_y = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    remaining = observation.get('remaining_resource_count', 0)

    def move_towards(target_x, target_y):
        dx = dy = 0
        if target_x > x:
            dx = 1
        elif target_x < x:
            dx = -1
        elif target_y > y:
            dy = 1
        elif target_y < y:
            dy = -1
        return [dx, dy]

    def safe(dx, dy):
        nx, ny = x + dx, y + dy
        if (nx, ny) in obstacles:
            return False
        if not (0 <= nx < width and 0 <= ny < height):
            return False
        return True

    if resources:
        target = min(resources, key=lambda r: abs(r[0]-x)+abs(r[1]-y))
        move = move_towards(target[0], target[1])
    else:
        move = [0, 0]

    # Prioritize avoiding opponent
    opp_dx = 0
    opp_dy = 0
    if abs(opponent_x - x) + abs(opponent_y - y) <= 2:
        away_x = x - opponent_x
        away_y = y - opponent_y
        if away_x != 0:
            opp_dx = 1 if away_x > 0 else -1
        if away_y != 0:
            opp_dy = 1 if away_y > 0 else -1
        # Try to move away if safe
        for dx, dy in [(opp_dx, 0), (0, opp_dy), (opp_dx, opp_dy)]:
            if safe(dx, dy):
                move = [dx, dy]
                break

    # If move leads to obstacle or out of bounds, stay
    if not safe(*move):
        move = [0, 0]
    return move
